-- Every candidate from the 726-row catalog review receives an explicit row-by-row decision.
update public.stat_categories category
set
  title=case when review.content_decision='approved' and nullif(review.player_title,'') is not null then review.player_title else category.title end,
  short_title=case when review.content_decision='approved' and nullif(review.player_title,'') is not null then left(review.player_title,70) else category.short_title end,
  description=case when review.content_decision='approved' and nullif(review.plain_description,'') is not null then review.plain_description else category.description end,
  plain_language_description=case when review.content_decision='approved' and nullif(review.plain_description,'') is not null then review.plain_description else category.plain_language_description end,
  content_review_status=review.content_decision,
  content_review_reason=review.reason,
  content_review_version='geostats-v14.3.1-content-review-v1',
  immediate_comprehension_score=review.comprehension_score,
  gameplay_interest_score=review.interest_score,
  uniqueness_score=review.uniqueness_score,
  curation_status=case when review.content_decision='excluded' then 'excluded' else category.curation_status end,
  curation_reason=case when review.content_decision='excluded' then review.reason else category.curation_reason end,
  player_quality_status=case when review.content_decision='excluded' then 'blocked' else category.player_quality_status end,
  player_quality_reason=case when review.content_decision='excluded' then review.reason else category.player_quality_reason end,
  enabled=case when review.content_decision='excluded' then false else category.enabled end,
  eligible_daily=case when review.content_decision='excluded' then false else category.eligible_daily end,
  metadata=coalesce(category.metadata,'{}'::jsonb)||jsonb_build_object(
    'contentReviewStatus',review.content_decision,
    'contentReviewReason',review.reason,
    'contentReviewVersion','geostats-v14.3.1-content-review-v1',
    'immediateComprehensionScore',review.comprehension_score,
    'gameplayInterestScore',review.interest_score,
    'uniquenessScore',review.uniqueness_score
  ),
  updated_at=now()
from v1431_content_review review
where category.source_organization=review.source_organization
  and category.source_indicator_code=review.source_indicator_code
  and category.title=review.previous_title;

-- Anything not represented in the full review table is explicitly pending and
-- cannot become playable merely because an importer supplied optimistic scores.
update public.stat_categories category
set
  content_review_status='pending',
  content_review_reason='Not included in the completed v14.3.1 category-by-category content review.',
  content_review_version='geostats-v14.3.1-content-review-v1',
  enabled=false,
  eligible_daily=false,
  updated_at=now()
where not exists (
  select 1 from v1431_content_review review
  where review.source_organization=category.source_organization
    and review.source_indicator_code=category.source_indicator_code
    and (review.previous_title=category.title or (review.player_title is not null and review.player_title=category.title))
);

-- World Bank has stable human-readable indicator pages showing the exact
-- indicator and country data. Restore the player experience that worked well.
update public.stat_categories
set
  player_source_url='https://data.worldbank.org/indicator/'||source_indicator_code,
  player_source_status='exact',
  player_source_reason='Official World Bank indicator page shows the exact indicator’s country data and chart.',
  player_source_checked_at=now(),
  link_quality_score=100,
  metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
    'playerSourceUrl','https://data.worldbank.org/indicator/'||source_indicator_code,
    'playerSourceStatus','exact',
    'playerSourcePolicyVersion','geostats-v14.3.1-player-link-v1'
  ),
  updated_at=now()
where source_organization='World Bank'
  and content_review_status='approved';

-- UIS exposes a readable browser, but the existing importer does not yet
-- produce a proven shareable URL with the exact indicator selected. It is
-- therefore handled by the same fail-closed rule as other non-World-Bank sources.

-- Generic landing pages, bulk archives, and machine-readable query URLs are
-- never substituted for a player source page.
update public.stat_categories
set
  player_source_url=null,
  player_source_status=case when source_organization='Natural Earth' then 'unavailable' else 'needs_exact_url' end,
  player_source_reason=case
    when source_organization='Natural Earth' then 'Natural Earth does not publish GeoStats’ exact derived ranking as a human-readable external data table.'
    else 'A verified human-readable deep link showing the exact filtered data has not been supplied.'
  end,
  player_source_checked_at=null,
  link_quality_score=0,
  enabled=false,
  eligible_daily=false,
  updated_at=now()
where source_organization<>'World Bank'
  and content_review_status='approved';

create or replace function public.player_source_url_is_safe(p_url text)
returns boolean
language sql
immutable
as $$
  select p_url is not null
    and p_url ~ '^https://'
    and p_url !~* '(^|[./])(api|comtradeapi)[.]'
    and p_url !~* '[.]((csv|tsv|json|xml|zip|gz|gzip|xlsx?|parquet))([?#]|$)'
    and p_url !~* '/(api|bulk|download|downloads)(/|$)'
    and p_url !~* '([?&])(format|download|output|type)=(csv|tsv|json|xml|zip|xlsx?|parquet)(&|$)'
    and p_url !~* '([?&])(download|attachment)='
$$;

create or replace function public.enforce_content_and_player_link_gate()
returns trigger
language plpgsql
as $$
begin
  if new.player_source_url is not null and not public.player_source_url_is_safe(new.player_source_url) then
    new.player_source_status:='invalid';
    new.player_source_reason:='Rejected because the URL is an API, raw file, bulk download, attachment, or non-HTTPS resource.';
    new.link_quality_score:=0;
  end if;

  if new.content_review_status<>'approved'
     or new.player_source_status<>'exact'
     or new.player_source_url is null
     or not public.player_source_url_is_safe(new.player_source_url)
     or coalesce(new.immediate_comprehension_score,0)<80
     or coalesce(new.gameplay_interest_score,0)<65
     or coalesce(new.link_quality_score,0)<90 then
    new.enabled:=false;
    new.eligible_daily:=false;
  end if;
  return new;
end;
$$;

drop trigger if exists stat_categories_content_player_link_gate on public.stat_categories;
create trigger stat_categories_content_player_link_gate
before insert or update on public.stat_categories
for each row execute function public.enforce_content_and_player_link_gate();

create or replace function public.record_player_source_validation(
  p_category_id text,
  p_status text,
  p_reason text,
  p_link_quality_score integer default null
)
returns text
language plpgsql
security definer
set search_path=public
as $$
begin
  if p_status not in ('exact','invalid','needs_exact_url','unavailable','pending') then
    raise exception 'Unsupported player source status: %',p_status;
  end if;
  update public.stat_categories
  set
    player_source_status=p_status,
    player_source_reason=p_reason,
    player_source_checked_at=case when p_status in ('exact','invalid','unavailable') then now() else null end,
    link_quality_score=coalesce(p_link_quality_score,case when p_status='exact' then 100 else 0 end),
    enabled=case when p_status='exact' then enabled else false end,
    eligible_daily=case when p_status='exact' then eligible_daily else false end,
    updated_at=now()
  where id=p_category_id;
  if not found then raise exception 'Category not found: %',p_category_id; end if;
  if p_status='exact' then
    perform public.apply_category_governance(p_category_id);
  end if;
  return p_status;
end;
$$;

create or replace view public.category_content_link_overview
with (security_invoker=true)
as
select
  count(*)::bigint as categories,
  count(*) filter(where content_review_status='approved')::bigint as content_approved,
  count(*) filter(where content_review_status='excluded')::bigint as content_excluded,
  count(*) filter(where content_review_status='pending')::bigint as content_pending,
  count(*) filter(where content_review_status='approved' and player_source_status='exact')::bigint as exact_player_links,
  count(*) filter(where content_review_status='approved' and player_source_status='pending')::bigint as links_pending,
  count(*) filter(where content_review_status='approved' and player_source_status in ('needs_exact_url','invalid','unavailable'))::bigint as links_blocked,
  count(*) filter(where enabled and eligible_daily)::bigint as playable
from public.stat_categories;

create or replace view public.category_content_link_issues
with (security_invoker=true)
as
select id,title,source_organization,source_indicator_code,
  content_review_status,content_review_reason,immediate_comprehension_score,gameplay_interest_score,
  player_source_status,player_source_url,player_source_reason,link_quality_score,
  enabled,eligible_daily
from public.stat_categories
where review_status<>'rejected'
  and (content_review_status='pending'
       or (content_review_status='approved' and (player_source_status<>'exact'
           or coalesce(immediate_comprehension_score,0)<80
           or coalesce(gameplay_interest_score,0)<65
           or coalesce(link_quality_score,0)<90)))
order by source_organization,title;

grant select on public.category_content_link_overview to service_role;
grant select on public.category_content_link_issues to service_role;
revoke all on function public.record_player_source_validation(text,text,text,integer) from public,anon,authenticated;
grant execute on function public.record_player_source_validation(text,text,text,integer) to service_role;

-- Re-run the existing concept-group selection. The trigger makes content and
-- player-link rules fail-closed even if an older governance function attempts
-- to enable a category that has not passed both gates.
do $$
declare row record;
begin
  for row in select distinct concept_group from public.stat_categories where concept_group is not null loop
    perform public.refresh_stat_concept_group(row.concept_group);
  end loop;
end;
$$;

commit;
